#include <vector>
#include <string>

struct NonDefault {
    int val;
    NonDefault(int v) : val(v) {}
    // No default constructor defined
};

int main() {
    std::vector<std::string> s_vec;
    // 1. Default construction
    s_vec.resize(5); // OK: string is DefaultConstructible (size 5, all empty strings)

    std::vector<int> i_vec;
    // 2. Copy construction
    i_vec.resize(5, 42); // OK: size 5, all elements are 42

    // std::vector<NonDefault> nd_vec;
    // nd_vec.resize(5); // COMPILE ERROR: NonDefault is not DefaultConstructible

    std::vector<NonDefault> nd_vec2;
    nd_vec2.resize(5, NonDefault(1)); // OK: uses copy construction
}
